// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testRegression_property() public {
        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;
        vm.prank(depositor);
        c.setL1BlockValues({
            _number: 1,
            _timestamp: 2,
            _basefee: 3,
            _hash: bytes32(0),
            _sequenceNumber: 4,
            _batcherHash: bytes32(0),
            _l1FeeOverhead: 5,
            _l1FeeScalar: 42
        });
        assertTrue(c.l1FeeScalar() == 42);
    }
}
